const fs = require('fs');
const path = require('path');
const http = require('http'); // use 'https' if your service is HTTPS

const VAULT_AUDIT_PATH = path.join(__dirname, 'vault-audit.txt');
const VAULT_CHECK_URL = 'http://localhost:3003/api/vault-check';

// Parse vault-audit.txt into an object
function parseVaultAuditFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split(/\r?\n/).filter(Boolean);

  const result = {};
  for (const line of lines) {
    // simple KEY=VALUE parsing
    const idx = line.indexOf('=');
    if (idx === -1) continue;
    const key = line.slice(0, idx).trim();
    const value = line.slice(idx + 1).trim();
    if (!key) continue;
    result[key] = value;
  }
  return result;
}

function postJson(url, data) {
  const { hostname, port, pathname: path } = new URL(url);
  const body = JSON.stringify(data);

  const options = {
    hostname,
    port: port || 80,
    path,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
    },
  };

  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let responseData = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => {
        responseData += chunk;
      });
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: responseData,
        });
      });
    });

    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function main() {
  try {
    const payload = parseVaultAuditFile(VAULT_AUDIT_PATH);

    // Optionally wrap in an object if your API expects a specific shape:
    // const payload = { secrets: parseVaultAuditFile(VAULT_AUDIT_PATH) };

    console.log('Posting payload to vault-check service...');
    const response = await postJson(VAULT_CHECK_URL, payload);

    console.log('Response status:', response.statusCode);
    console.log('Response headers:', response.headers);
    console.log('Response body:', response.body);
  } catch (err) {
    console.error('Error posting to vault-check:', err);
    process.exit(1);
  }
}

main();
```

